#!/usr/bin/env python3
"""Genome-specific neural start ranker: learned replacement for the 28-bin RBS prior.

Same inputs as ``tools/rbs_start_prior.py`` -- this genome's FASTA and our own
pass-1 predictions, no reference annotation, no cross-genome pretraining -- but
the statistic is learned instead of binned. The current prior asserts

    useful information = Prodigal's 28 motif/spacer categories

whereas this asks the weaker question

    what sequence pattern distinguishes selected starts from their own
    competing in-frame starts?

Training unit is one ORF, not one start. For each pass-1 predicted ORF the
chosen start is the pseudo-positive and **every other valid in-frame start
sharing the same stop** is a negative. Those are hard negatives by
construction: in-frame, canonical start codons, sitting inside sequence that
already looks coding, so the model cannot win with a "coding-looking = positive"
shortcut. Loss is a listwise softmax over that candidate set, averaged per ORF::

    L = -1/G * sum_g log( exp(q_g*/tau) / sum_i exp(q_gi/tau) )

Averaging per ORF (not per candidate) is deliberate: an ORF with 40
alternatives must not carry 13x the gradient of one with 3, and there is no
global class imbalance to reweight -- 4,000 genes is 4,000 ranking problems, not
4,000 positives against 84,000 negatives. Scores are unbounded utilities;
nothing requires the positive to exceed 0.5 or negatives to fall below it, only
q_true > q_alt *within its own ORF*. That is also why the decode-side term is
centred per ORF (see ``--center``): the ranker should change which start wins,
not whether the gene exists.

Two hazards specific to self-training, both handled:

  *Label noise.* The pseudo-positive is our pass-1 start, and mis-called starts
  are exactly the failure mode. If a locus' true start is its own hardest
  negative, naive training reinforces the error. ``--conf-*`` restricts or
  down-weights training ORFs by the CNN's own START-channel probability and by
  ORF length -- both available at inference.

  *Memorisation.* A few thousand ORFs against even ~8k parameters can memorise.
  Every reported number is **out-of-fold**: ``--folds`` models are trained, each
  scoring only the ORFs it never saw.

Three models share the loss so the comparison is controlled:

  ``bins``  28-bin one-hot + start codon + log length -> linear. The current
            prior's information with learned weights; separates "better
            weighting" from "better features".
  ``feat``  the above plus explicit purine-motif/spacer/composition features -> MLP.
  ``cnn``   raw 60 nt one-hot -> small 1D CNN. Learns its own motifs.

Usage::

    python tools/start_ranker.py \
      --genome-fasta   <fna> \
      --predictions-gff3 <pass1.gff3> \
      --nn-probs       <nn_probs dir>        # optional, for confidence
      --model cnn --folds 4 \
      --out results/start_ranker/k12 \
      --reference-gff  <ref.gff>             # EVALUATION ONLY, never trained on
"""
from __future__ import annotations

import argparse
import json
import math
import sys
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    pass

from .prodigal_rbs_bins import prodigal_rbs_bin_from_upstream  # noqa: E402
from .rbs_start_prior import alt_starts, load_fasta, revcomp  # noqa: E402

# Window: 45 nt upstream (matches the bin prior's window exactly, and covers
# Prodigal's longest motif+spacer) then the start codon and 12 nt into the gene.
UP_NT = 45
DOWN_NT = 15
WIN = UP_NT + DOWN_NT

# 11-channel NN layout (hmm_prokaryotic.slice_{plus,minus}_channels):
# 0=IGR, 1-3=CDS+ frames, 4-6=CDS- frames, 7=START+, 8=START-, 9/10=STOP+/-.
CH_START_PLUS, CH_START_MINUS = 7, 8

_BASE_CODE = {"A": 0, "C": 1, "G": 2, "T": 3}

# Local copies of tools.fp_coding_potential.{parse_gff,stop_key}. Importing that
# module drags in pseudogene_frame_utils -> export_nn_probs_tracks, whose cluster
# copy is older and lacks MINUS_FRAME_NAMES; this module must stay importable
# from the decoder and on the cluster, so the chain is cut here deliberately.
# Semantics must match exactly: 0-based half-open [lo, hi).
Feat = Tuple[str, int, int, str]


def parse_gff(path: Path, features: Sequence[str],
              seqid: Optional[str]) -> List[Feat]:
    want = set(features)
    out: List[Feat] = []
    with path.open() as fh:
        for line in fh:
            if line.startswith("#"):
                continue
            f = line.rstrip("\n").split("\t")
            if len(f) < 9 or f[2] not in want:
                continue
            if seqid and f[0] != seqid:
                continue
            out.append((f[0], int(f[3]) - 1, int(f[4]), f[6]))
    return out


def stop_key(f: Feat) -> Tuple[str, int, str]:
    """The 3' terminus -- the stop codon end, which is strand-dependent."""
    sid, lo, hi, strand = f
    return (sid, hi, strand) if strand == "+" else (sid, lo, strand)

_CODON_IDX = {"ATG": 0, "GTG": 1, "TTG": 2}


# --------------------------------------------------------------------------
# candidate-set extraction
# --------------------------------------------------------------------------

def encode_window(seq: str, lo: int, hi: int, strand: str) -> Optional[np.ndarray]:
    """uint8 base codes (N=4) for the WIN nt around this start, gene-oriented."""
    if strand == "+":
        a, b = lo - UP_NT, lo + DOWN_NT
        if a < 0 or b > len(seq):
            return None
        w = seq[a:b]
    else:
        a, b = hi - DOWN_NT, hi + UP_NT
        if a < 0 or b > len(seq):
            return None
        w = revcomp(seq[a:b])
    out = np.full(WIN, 4, dtype=np.uint8)
    for i, ch in enumerate(w):
        c = _BASE_CODE.get(ch)
        if c is not None:
            out[i] = c
    return out


@dataclass
class CandSet:
    """Flat candidate storage; ``offsets[g]:offsets[g+1]`` indexes ORF g."""
    win: np.ndarray                     # (N, WIN) uint8
    offsets: np.ndarray                 # (G+1,) int64
    pos_idx: np.ndarray                 # (G,) int32 -- pseudo-positive slot
    length: np.ndarray                  # (N,) int32 -- ORF length from this start
    start_p: np.ndarray                 # (N,) float32 -- CNN START prob (or nan)
    coord: np.ndarray                   # (N, 2) int64 -- forward (lo, hi)
    seqid: List[str] = field(default_factory=list)   # (G,)
    strand: List[str] = field(default_factory=list)  # (G,)

    def n_orf(self) -> int:
        return len(self.offsets) - 1

    def slice(self, g: int) -> slice:
        return slice(int(self.offsets[g]), int(self.offsets[g + 1]))


def build_candidates(seqs: Dict[str, str],
                     genes: Sequence[Tuple[str, int, int, str]],
                     *, min_nt: int = 30,
                     probs: Optional[Dict[str, np.ndarray]] = None,
                     max_cand: int = 64,
                     rng: Optional[np.random.Generator] = None) -> CandSet:
    """Candidate sets for the given ORFs; slot 0 of each set is the given start."""
    rng = rng or np.random.default_rng(0)
    W: List[np.ndarray] = []
    L: List[np.ndarray] = []
    P: List[np.ndarray] = []
    C: List[np.ndarray] = []
    counts: List[int] = []
    sids: List[str] = []
    strands: List[str] = []
    for seqid, lo, hi, strand in genes:
        seq = seqs.get(seqid)
        if seq is None:
            continue
        cands = [(lo, hi)] + alt_starts(seq, lo, hi, strand, min_nt=min_nt)
        if len(cands) < 2:
            continue  # no decision to learn from or to make
        if len(cands) > max_cand:
            keep = rng.choice(len(cands) - 1, max_cand - 1, replace=False) + 1
            cands = [cands[0]] + [cands[i] for i in sorted(keep)]
        enc = [encode_window(seq, a, b, strand) for a, b in cands]
        if any(e is None for e in enc):
            continue
        W.append(np.stack(enc))
        L.append(np.array([b - a for a, b in cands], dtype=np.int32))
        C.append(np.array(cands, dtype=np.int64))
        if probs is not None and seqid in probs:
            ch = CH_START_PLUS if strand == "+" else CH_START_MINUS
            pr = probs[seqid]
            P.append(np.array([pr[a if strand == "+" else b - 1, ch]
                               for a, b in cands], dtype=np.float32))
        else:
            P.append(np.full(len(cands), np.nan, dtype=np.float32))
        counts.append(len(cands))
        sids.append(seqid)
        strands.append(strand)
    cnt = np.array(counts, dtype=np.int64)
    return CandSet(win=np.concatenate(W),
                   offsets=np.concatenate([[0], cnt.cumsum()]),
                   pos_idx=np.zeros(len(cnt), dtype=np.int32),
                   length=np.concatenate(L), start_p=np.concatenate(P),
                   coord=np.concatenate(C), seqid=sids, strand=strands)


# --------------------------------------------------------------------------
# feature models (controls)
# --------------------------------------------------------------------------

_BASES = np.array(list("ACGTN"))


def bin_features(win: np.ndarray, length: np.ndarray) -> np.ndarray:
    """[28 one-hot RBS bin | 3 one-hot start codon | log10 ORF length] (32 dims).

    Exactly the information the current prior sees, so a linear model on this is
    the "same features, learned weights" control.
    """
    out = np.zeros((win.shape[0], 32), dtype=np.float32)
    for i in range(win.shape[0]):
        s = "".join(_BASES[win[i]])
        out[i, prodigal_rbs_bin_from_upstream(s[:UP_NT])] = 1.0
        ci = _CODON_IDX.get(s[UP_NT:UP_NT + 3])
        if ci is not None:
            out[i, 28 + ci] = 1.0
        out[i, 31] = math.log10(max(int(length[i]), 1))
    return out


def rich_features(win: np.ndarray, length: np.ndarray) -> np.ndarray:
    """bin_features plus purine-motif / spacer / composition features (38 dims)."""
    base = bin_features(win, length)
    extra = np.zeros((win.shape[0], 6), dtype=np.float32)
    for i in range(win.shape[0]):
        up = win[i][:UP_NT]
        best_len, best_sp = 0, 0
        for mlen in (6, 5, 4, 3):
            for j in range(UP_NT - mlen + 1):
                w = up[j:j + mlen]
                if np.isin(w, [0, 2]).all() and (w == 2).any():  # A/G run with a G
                    best_len, best_sp = mlen, UP_NT - (j + mlen)
                    break
            if best_len:
                break
        extra[i, 0] = best_len
        extra[i, 1] = min(best_sp, 30) / 30.0
        extra[i, 2] = (up == 2).mean()
        extra[i, 3] = (up == 0).mean()
        extra[i, 4] = np.isin(win[i][UP_NT:], [1, 2]).mean()
        extra[i, 5] = np.isin(up, [1, 2]).mean()
    return np.concatenate([base, extra], axis=1)


FEATFN = {"bins": bin_features, "feat": rich_features}


def build_model(kind: str, width: int = 24, kernel: int = 7, pos_bins: int = 8):
    import torch.nn as nn
    import torch.nn.functional as F

    if kind == "cnn":
        class CNN(nn.Module):
            """Raw 60 nt -> score. Kept to ~8k params: one genome supplies only a
            few thousand ranking problems, so capacity is the binding risk."""

            def __init__(self) -> None:
                super().__init__()
                p = kernel // 2
                self.c1 = nn.Conv1d(4, width, kernel, padding=p)
                self.c2 = nn.Conv1d(width, width, kernel, padding=p)
                self.drop = nn.Dropout(0.3)
                # Coarse positional pooling, not global: RBS spacing is
                # positional, but 60 exact offsets would overfit.
                self.pool_to = pos_bins
                self.h1 = nn.Linear(width * pos_bins, 16)
                self.h2 = nn.Linear(16, 1)

            def forward(self, x):  # x: (B, WIN) int64
                oh = F.one_hot(x.clamp(max=4), 5)[..., :4].float().transpose(1, 2)
                z = F.relu(self.c1(oh))
                z = F.max_pool1d(z, 2)
                z = F.relu(self.c2(z))
                z = F.adaptive_max_pool1d(z, self.pool_to)
                z = self.drop(z.flatten(1))
                return self.h2(F.relu(self.h1(z))).squeeze(-1)

        return CNN()

    n_feat = 32 if kind == "bins" else 38
    if kind == "bins":
        class Lin(nn.Module):
            def __init__(self) -> None:
                super().__init__()
                self.w = nn.Linear(n_feat, 1)

            def forward(self, x):
                return self.w(x).squeeze(-1)

        return Lin()

    class MLP(nn.Module):
        def __init__(self) -> None:
            super().__init__()
            self.net = nn.Sequential(nn.Linear(n_feat, 24), nn.ReLU(),
                                     nn.Linear(24, 1))

        def forward(self, x):
            return self.net(x).squeeze(-1)

    return MLP()


# --------------------------------------------------------------------------
# listwise training
# --------------------------------------------------------------------------

def pad_batch(cs: CandSet, idx: np.ndarray, feats: Optional[np.ndarray]):
    """(B, Kmax, ...) padded candidate sets plus a validity mask."""
    lo, hi = cs.offsets[idx], cs.offsets[idx + 1]
    kmax = int((hi - lo).max())
    dim = WIN if feats is None else feats.shape[1]
    x = np.zeros((len(idx), kmax, dim), dtype=np.int64 if feats is None else np.float32)
    mask = np.zeros((len(idx), kmax), dtype=bool)
    for r, (a, b) in enumerate(zip(lo, hi)):
        src = cs.win[a:b] if feats is None else feats[a:b]
        x[r, :b - a] = src
        mask[r, :b - a] = True
    return x, mask, cs.pos_idx[idx].astype(np.int64)


def confidence(cs: CandSet, *, min_len: int, min_margin: float) -> np.ndarray:
    """Per-ORF trainability: is this pass-1 start reliable enough to learn from?

    Both signals are available at inference. Length, because a long ORF's stop
    is essentially certain and its start is chosen from better evidence; and the
    CNN's own START margin between the chosen start and its best competitor,
    because a near-tie is exactly the case where pass-1 may be wrong.
    """
    keep = np.ones(cs.n_orf(), dtype=bool)
    for g in range(cs.n_orf()):
        sl = cs.slice(g)
        if int(cs.length[sl][0]) < min_len:
            keep[g] = False
            continue
        p = cs.start_p[sl]
        if min_margin > 0 and not np.isnan(p).any():
            rest = np.delete(p, 0)
            if rest.size and float(p[0]) - float(rest.max()) < min_margin:
                keep[g] = False
    return keep


def listwise_loss(q, mask, pos_idx, tau: float):
    import torch.nn.functional as F
    q = (q / tau).masked_fill(~mask, float("-inf"))
    return F.cross_entropy(q, pos_idx)


def score_all(model, cs: CandSet, feats, device, batch: int = 2048,
              orfs: Optional[np.ndarray] = None) -> np.ndarray:
    """Flat per-candidate scores in CandSet order; nan outside ``orfs``."""
    import torch
    model.eval()
    x = cs.win.astype(np.int64) if feats is None else feats
    out = np.full(x.shape[0], np.nan, dtype=np.float32)
    if orfs is None:
        rows = np.arange(x.shape[0])
    else:
        rows = np.concatenate([np.arange(cs.offsets[g], cs.offsets[g + 1])
                               for g in orfs]) if len(orfs) else np.zeros(0, int)
    with torch.no_grad():
        for s in range(0, rows.shape[0], batch):
            sel = rows[s:s + batch]
            xt = torch.as_tensor(x[sel], device=device)
            out[sel] = model(xt).float().cpu().numpy()
    return out


def orf_metrics(cs: CandSet, scores: np.ndarray, which: np.ndarray) -> Dict[str, float]:
    """Ranking quality of the pseudo-positive, over the ORFs in ``which``."""
    top1 = top3 = n = 0
    ranks: List[int] = []
    for g in np.flatnonzero(which):
        row = scores[cs.slice(g)]
        tv = row[cs.pos_idx[g]]
        r = int((row > tv).sum()) + 1
        ranks.append(r)
        top1 += r == 1
        top3 += r <= 3
        n += 1
    return {"n": n, "top1": top1 / max(n, 1), "top3": top3 / max(n, 1),
            "mean_rank": float(np.mean(ranks)) if ranks else 0.0}


def train_fold(cs: CandSet, train_orfs: np.ndarray, feats, args, seed: int):
    """Fit one model on ``train_orfs``; early-stop on a 10% inner split."""
    import torch
    torch.manual_seed(seed)
    dev = torch.device(args.device)
    rng = np.random.default_rng(seed)
    tr = train_orfs.copy()
    rng.shuffle(tr)
    cut = max(1, int(0.1 * len(tr)))
    inner_val, inner_tr = tr[:cut], tr[cut:]

    model = build_model(args.model, args.width, args.kernel).to(dev)
    opt = torch.optim.AdamW(model.parameters(), lr=args.lr, weight_decay=args.wd)
    best, best_state, bad = -1.0, None, 0
    for ep in range(1, args.epochs + 1):
        model.train()
        perm = rng.permutation(inner_tr)
        tot = nb = 0.0
        for s in range(0, len(perm), args.batch):
            idx = np.sort(perm[s:s + args.batch])
            x, m, t = pad_batch(cs, idx, feats)
            xt = torch.as_tensor(x, device=dev)
            q = model(xt.reshape(-1, x.shape[-1])).reshape(x.shape[0], x.shape[1])
            loss = listwise_loss(q, torch.as_tensor(m, device=dev),
                                 torch.as_tensor(t, device=dev), args.tau)
            opt.zero_grad()
            loss.backward()
            opt.step()
            tot += loss.detach().item()
            nb += 1
        sc = score_all(model, cs, feats, dev, orfs=inner_val)
        mv = orf_metrics(cs, sc, np.isin(np.arange(cs.n_orf()), inner_val))
        if mv["top1"] > best:
            best, bad = mv["top1"], 0
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
        else:
            bad += 1
            if bad >= args.patience:
                break
        if args.verbose:
            print(f"    ep{ep:>3} loss {tot/max(nb,1):.4f} inner-val top1 {mv['top1']:.4f}",
                  flush=True)
    if best_state is None:
        raise RuntimeError("no epoch completed; training set too small")
    model.load_state_dict(best_state)
    return model, best, ep


# --------------------------------------------------------------------------
# 28-bin baseline, scored on the identical candidate sets
# --------------------------------------------------------------------------

def assign_bins(cs: CandSet) -> np.ndarray:
    """Prodigal RBS bin of every candidate, computed once."""
    out = np.empty(cs.win.shape[0], dtype=np.int16)
    for i in range(cs.win.shape[0]):
        out[i] = prodigal_rbs_bin_from_upstream("".join(_BASES[cs.win[i]][:UP_NT]))
    return out


def bin_log_odds(cs: CandSet, bins: np.ndarray, train_orfs: np.ndarray) -> Dict[int, float]:
    """The existing prior's statistic, refit on the same training ORFs."""
    pred = np.zeros(28, dtype=np.int64)
    alt = np.zeros(28, dtype=np.int64)
    for g in train_orfs:
        sl = cs.slice(g)
        b = bins[sl]
        p = int(cs.pos_idx[g])
        pred[b[p]] += 1
        alt += np.bincount(np.delete(b, p), minlength=28)
    npred, nalt = max(pred.sum(), 1), max(alt.sum(), 1)
    return {b: math.log(((pred[b] + 1) / (npred + 28)) /
                        ((alt[b] + 1) / (nalt + 28))) for b in range(28)}


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------

def load_probs(d: Optional[Path]) -> Optional[Dict[str, np.ndarray]]:
    if d is None:
        return None
    man = json.loads((d / "nn_probs_manifest.json").read_text())
    return {k: np.load(d / v["file"], mmap_mode="r")
            for k, v in man["sequences"].items()}


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--genome-fasta", type=Path, required=True)
    ap.add_argument("--predictions-gff3", type=Path, required=True,
                    help="pass-1 predictions; their starts are the pseudo-positives")
    ap.add_argument("--nn-probs", type=Path, default=None,
                    help="nn_probs dir, for START-margin confidence filtering")
    ap.add_argument("--reference-gff", type=Path, default=None,
                    help="EVALUATION ONLY. Never used for training or scoring.")
    ap.add_argument("--out", type=Path, required=True, help="output prefix")
    ap.add_argument("--model", choices=["bins", "feat", "cnn"], default="cnn")
    ap.add_argument("--folds", type=int, default=4)
    ap.add_argument("--min-nt", type=int, default=30)
    ap.add_argument("--conf-min-len", type=int, default=0,
                    help="train only on pass-1 ORFs at least this long (nt)")
    ap.add_argument("--conf-min-margin", type=float, default=0.0,
                    help="train only where the CNN START prob beats its best "
                         "competitor by at least this much")
    ap.add_argument("--epochs", type=int, default=40)
    ap.add_argument("--batch", type=int, default=64)
    ap.add_argument("--lr", type=float, default=3e-3)
    ap.add_argument("--wd", type=float, default=1e-3)
    ap.add_argument("--tau", type=float, default=1.0)
    ap.add_argument("--width", type=int, default=24)
    ap.add_argument("--kernel", type=int, default=7)
    ap.add_argument("--patience", type=int, default=6)
    ap.add_argument("--device", default="cpu")
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--verbose", action="store_true")
    args = ap.parse_args()

    import torch

    # Honour the thread caps the caller set. torch otherwise grabs every visible
    # core, which on a shared 16-CPU allocation running several genomes at once
    # gave load average 43 and a 2.5x slowdown (cluster job 25983).
    import os
    _nt = os.environ.get("OMP_NUM_THREADS") or os.environ.get("TORCH_NUM_THREADS")
    if _nt:
        torch.set_num_threads(max(1, int(_nt)))
    print(f"torch threads: {torch.get_num_threads()}", flush=True)

    t0 = time.time()
    seqs = {k: v.upper() for k, v in load_fasta(args.genome_fasta).items()}
    probs = load_probs(args.nn_probs)
    genes: List[Tuple[str, int, int, str]] = []
    for sid in seqs:
        genes += parse_gff(args.predictions_gff3, ["CDS"], sid)
    print(f"pass-1 predictions: {len(genes)} CDS over {len(seqs)} contig(s)")

    cs = build_candidates(seqs, genes, min_nt=args.min_nt, probs=probs,
                          rng=np.random.default_rng(args.seed))
    ncand = cs.win.shape[0]
    print(f"candidate sets: {cs.n_orf()} ORFs, {ncand} candidates "
          f"(median {int(np.median(np.diff(cs.offsets)))} per ORF)  "
          f"[{time.time()-t0:.0f}s]")

    trainable = confidence(cs, min_len=args.conf_min_len,
                           min_margin=args.conf_min_margin)
    print(f"trainable ORFs after confidence filter: {int(trainable.sum())}"
          f"/{cs.n_orf()}")

    print("assigning 28 RBS bins (baseline) ...", flush=True)
    bins = assign_bins(cs)
    feats = None
    if args.model in FEATFN:
        print("featurising ...", flush=True)
        feats = FEATFN[args.model](cs.win, cs.length)

    rng = np.random.default_rng(args.seed)
    fold_of = rng.integers(0, args.folds, size=cs.n_orf())
    nn_scores = np.full(ncand, np.nan, dtype=np.float32)
    bin_sc = np.full(ncand, np.nan, dtype=np.float32)

    for f in range(args.folds):
        held = fold_of == f
        # folds == 1 is production mode: one model trained on every trainable
        # ORF and applied to all of them. Out-of-fold honesty needs folds >= 2;
        # with a single fold "~held" is empty, which would train on nothing.
        tr = (np.flatnonzero(trainable) if args.folds <= 1
              else np.flatnonzero((~held) & trainable))
        if tr.size == 0:
            raise SystemExit(f"fold {f}: no trainable ORFs -- refusing to save "
                             f"an untrained model")
        print(f"fold {f}: train {len(tr)} ORFs, score {int(held.sum())} held-out",
              flush=True)
        model, inner, eps = train_fold(cs, tr, feats, args, args.seed * 100 + f)
        sc = score_all(model, cs, feats, torch.device(args.device),
                       orfs=np.flatnonzero(held))
        lo = bin_log_odds(cs, bins, tr)
        bsc = np.array([lo[int(b)] for b in bins], dtype=np.float32)
        for g in np.flatnonzero(held):
            sl = cs.slice(g)
            nn_scores[sl] = sc[sl]
            bin_sc[sl] = bsc[sl]
        torch.save({"model": args.model, "width": args.width, "kernel": args.kernel,
                    "state": model.state_dict(), "up_nt": UP_NT, "down_nt": DOWN_NT,
                    "bin_log_odds": lo, "fold": f, "inner_top1": inner},
                   Path(f"{args.out}.fold{f}.pt"))
        print(f"        inner-val top1 {inner:.4f} after {eps} epochs", flush=True)

    allo = np.ones(cs.n_orf(), dtype=bool)
    mn = orf_metrics(cs, nn_scores, allo)
    mb = orf_metrics(cs, bin_sc, allo)
    print(f"\nOUT-OF-FOLD agreement with pass-1 start ({mn['n']} ORFs)")
    print(f"  {args.model:5s}   top1 {mn['top1']:.4f}  top3 {mn['top3']:.4f}  "
          f"mean rank {mn['mean_rank']:.2f}")
    print(f"  28-bin  top1 {mb['top1']:.4f}  top3 {mb['top3']:.4f}  "
          f"mean rank {mb['mean_rank']:.2f}")

    np.savez_compressed(Path(f"{args.out}.oof.npz"), nn=nn_scores, bins=bin_sc,
                        offsets=cs.offsets, pos_idx=cs.pos_idx, coord=cs.coord,
                        length=cs.length, seqid=np.array(cs.seqid, dtype=object),
                        strand=np.array(cs.strand, dtype=object))

    if args.reference_gff is not None:
        gate(cs, nn_scores, bin_sc, args, seqs)
    print(f"\ntotal {time.time()-t0:.0f}s")


def gate(cs: CandSet, nn_scores: np.ndarray, bin_sc: np.ndarray,
         args: argparse.Namespace, seqs: Dict[str, str]) -> None:
    """The decisive diagnostic. Reference used for EVALUATION only.

    At loci where pass-1 chose the wrong start, does the ranker place the true
    start above the one pass-1 chose? Scored out-of-fold, head-to-head against
    the 28-bin log-odds on identical candidate sets.
    """
    ref: List[Tuple[str, int, int, str]] = []
    for sid in seqs:
        ref += parse_gff(args.reference_gff, ["CDS"], sid)
    refstop = {stop_key(r): r for r in ref}

    def truth_slot(g: int) -> Optional[int]:
        """Which candidate slot is the annotated start, if this ORF is real."""
        sl = cs.slice(g)
        key = stop_key((cs.seqid[g], int(cs.coord[sl][0][0]),
                        int(cs.coord[sl][0][1]), cs.strand[g]))
        r = refstop.get(key)
        if r is None:
            return None
        hits = np.flatnonzero((cs.coord[sl][:, 0] == r[1]) &
                              (cs.coord[sl][:, 1] == r[2]))
        return int(hits[0]) if hits.size else None

    rows = []
    for g in range(cs.n_orf()):
        ts = truth_slot(g)
        if ts is None:
            continue
        rows.append((g, ts))
    correct = [(g, t) for g, t in rows if t == cs.pos_idx[g]]
    wrong = [(g, t) for g, t in rows if t != cs.pos_idx[g]]

    print(f"\nGATING CHECK (reference used for evaluation only)")
    print(f"  pass-1 ORFs matched to a reference stop : {len(rows)}")
    print(f"    pass-1 start already correct          : {len(correct)}")
    print(f"    pass-1 start wrong                    : {len(wrong)}")

    def head_to_head(name: str, sc: np.ndarray) -> Dict[str, float]:
        better = worse = tie = 0
        for g, t in wrong:
            sl = cs.slice(g)
            row = sc[sl]
            if row[t] > row[cs.pos_idx[g]]:
                better += 1
            elif row[t] < row[cs.pos_idx[g]]:
                worse += 1
            else:
                tie += 1
        top = sum(1 for g, t in wrong
                  if int(np.argmax(sc[cs.slice(g)])) == t)
        kept = sum(1 for g, t in correct
                   if int(np.argmax(sc[cs.slice(g)])) == t)
        d = max(better + worse, 1)
        print(f"  {name:7s} prefers TRUE over pass-1's wrong start: "
              f"{better:>4}/{len(wrong)} ({better/max(len(wrong),1):.1%})  "
              f"[decisive {better}/{better+worse} = {better/d:.1%}, tie {tie}]")
        print(f"  {name:7s}   ranks the TRUE start #1 at those loci  : "
              f"{top:>4}/{len(wrong)} ({top/max(len(wrong),1):.1%})")
        print(f"  {name:7s}   keeps already-correct starts #1        : "
              f"{kept:>4}/{len(correct)} ({kept/max(len(correct),1):.1%})")
        return {"better": better, "worse": worse, "tie": tie, "top1_wrong": top,
                "kept_correct": kept, "n_wrong": len(wrong), "n_correct": len(correct)}

    res = {args.model: head_to_head(args.model, nn_scores),
           "bins28": head_to_head("28-bin", bin_sc)}
    Path(f"{args.out}.gate.json").write_text(json.dumps(res, indent=2))


if __name__ == "__main__":
    main()
